export const campCabins: CampCabin[] = [...fragment1, ...fragment2]

// Case-insensitive lookup: vue-router matches static routes case-insensitively,
// so the dynamic route must behave the same. Canonicals always come from the
// returned cabin's slug, never from the request params.
export const findCabin = <T extends CabinBase>(list: T[], slug: string) =>
  list.find((c) => c.slug.toLowerCase() === slug.toLowerCase())

// Reproduces the JSON-LD blocks of the original cabin pages field-for-field,
// in the same key order, so the serialised output is unchanged.
export const buildCabinJsonLd = (jsonLd: CabinJsonLd) => ({
  '@context': 'https://schema.org',
  '@type': 'LodgingBusiness',
  name: 'Camp Alta Kiruna',
  url: 'https://campalta.net',
  containsPlace: {
    '@type': 'Accommodation',
    name: jsonLd.name,
    description: jsonLd.description,
    occupancy: { '@type': 'QuantitativeValue', maxValue: jsonLd.occupancy },
    floorSize: { '@type': 'QuantitativeValue', value: jsonLd.floorSizeM2, unitCode: 'MTK' },
    amenityFeature: jsonLd.amenities.map((name) => ({
      '@type': 'LocationFeatureSpecification',
      name,
    })),
  },
})
